function Graph({relationships,entities,onNode,onEdge}:{relationships:Relationship[],entities:CanonicalEntity[],onNode:(id:string)=>void,onEdge:(r:Relationship)=>void}){
 const ids=Array.from(new Set(relationships.flatMap(r=>[r.source.id,r.target.id]))); const nodes=ids.map(id=>entities.find(e=>e.id===id)).filter(Boolean) as CanonicalEntity[]; if(!nodes.length)return <div className="muted">No relationships match the current filter.</div>; const cx=450,cy=210,rx=330,ry=145; const pos=new Map(nodes.map((n,i)=>{const a=Math.PI*2*i/nodes.length-Math.PI/2;return [n.id,{x:cx+rx*Math.cos(a),y:cy+ry*Math.sin(a)}]})); return <div style={{overflowX:'auto',border:'1px solid #ddd',borderRadius:12}}><svg viewBox="0 0 900 420" style={{width:'100%',minWidth:700,height:420}}>{relationships.map(r=>{const a=pos.get(r.source.id)!,b=pos.get(r.target.id)!;return <g key={r.id} onClick={()=>onEdge(r)} style={{cursor:'pointer'}}><line x1={a.x} y1={a.y} x2={b.x} y2={b.y} stroke="#999" strokeWidth="2"/><text x={(a.x+b.x)/2} y={(a.y+b.y)/2-5} textAnchor="middle" fontSize="11">{r.schema}</text></g>})}{nodes.map(n=>{const p=pos.get(n.id)!;return <g key={n.id} transform={`translate(${p.x} ${p.y})`} onClick={()=>onNode(n.id)} style={{cursor:'pointer'}}><circle r="31" fill="white" stroke="#222" strokeWidth="2"/><text textAnchor="middle" y="4" fontSize="12">{n.caption.length>22?n.caption.slice(0,21)+'…':n.caption}</text><text textAnchor="middle" y="17" fontSize="10" fill="#777">{n.schema}</text></g>})}</svg></div>
}

