 const [relationships,setRelationships]=useState<Relationship[]>([]); const [graphSchemas,setGraphSchemas]=useState<Set<string>>(new Set()); const [includeGraphDuplicates,setIncludeGraphDuplicates]=useState(false); const [graphReconciliation,setGraphReconciliation]=useState<GraphResponse['reconciliation']>({collapsed_by_default:true,suppressed_duplicate_count:0,underlying_edge_count:0,visible_edge_count:0}); const [graphEdge,setGraphEdge]=useState<Relationship|null>(null); const [relationshipEvidenceReviews,setRelationshipEvidenceReviews]=useState<RelationshipEvidenceReview[]>([]); const [relationshipEvidenceRationale,setRelationshipEvidenceRationale]=useState(''); const [relationshipEvidenceStatus,setRelationshipEvidenceStatus]=useState(''); const [relationshipEvidenceAttachId,setRelationshipEvidenceAttachId]=useState(''); const [relationshipEvidenceAttachNote,setRelationshipEvidenceAttachNote]=useState(''); const [relSchema,setRelSchema]=useState('Ownership'); const [relSource,setRelSource]=useState(''); const [relTarget,setRelTarget]=useState(''); const [relRole,setRelRole]=useState(''); const [relEvidence,setRelEvidence]=useState('');
