 const [documents,setDocuments]=useState<DocItem[]>([]); const [docCandidates,setDocCandidates]=useState<ExtractionCandidate[]>([]); const [relationshipClaimCandidate,setRelationshipClaimCandidate]=useState<ExtractionCandidate|null>(null); const [extractionRelSchema,setExtractionRelSchema]=useState('Directorship'); const [extractionRelSource,setExtractionRelSource]=useState(''); const [extractionRelTarget,setExtractionRelTarget]=useState(''); const [docFile,setDocFile]=useState<File|null>(null); const [docTitle,setDocTitle]=useState(''); const [docStatus,setDocStatus]=useState(''); const [openAlephReview,setOpenAlephReview]=useState<Record<string,OpenAlephReviewStatus>>({});
