 const [sources,setSources]=useState<SourceRecord[]>([]); const [sourceTitle,setSourceTitle]=useState(''); const [sourceUrl,setSourceUrl]=useState(''); const [sourceType,setSourceType]=useState('web'); const [evidenceQuote,setEvidenceQuote]=useState(''); const [evidenceLocator,setEvidenceLocator]=useState(''); const [evidenceNotes,setEvidenceNotes]=useState(''); const [sourceCaptureStatus,setSourceCaptureStatus]=useState('');
 const [apiTokenInput,setApiTokenInput]=useState(''); const [apiAccessState,setApiAccessState]=useState<'checking'|'local'|'authenticated'|'needs_token'|'remote_disabled'|'error'>('checking'); const [apiAccessMessage,setApiAccessMessage]=useState('Checking API access…');
 const [backupFile,setBackupFile]=useState<File|null>(null); const [backupPreview,setBackupPreview]=useState<BackupPreview|null>(null); const [backupConfirmed,setBackupConfirmed]=useState(false); const [backupStatus,setBackupStatus]=useState(''); const [settingsStatus,setSettingsStatus]=useState<SettingsStatus|null>(null); const [credentialProvider,setCredentialProvider]=useState<'aleph'|'opensanctions'>('aleph'); const [credentialValue,setCredentialValue]=useState(''); const [credentialStatus,setCredentialStatus]=useState(''); const [deletePreview,setDeletePreview]=useState<InvestigationDeletionPreview|null>(null); const [deleteConfirmation,setDeleteConfirmation]=useState(''); const [deleteStatus,setDeleteStatus]=useState(''); const [orphanPreview,setOrphanPreview]=useState<OrphanStoragePreview|null>(null); const [orphanStatus,setOrphanStatus]=useState(''); const [securityAudit,setSecurityAudit]=useState<SecurityAuditView|null>(null); const [securityAuditSummary,setSecurityAuditSummary]=useState<SecurityAuditSummary|null>(null); const [securityAuditRetention,setSecurityAuditRetention]=useState<SecurityAuditRetentionPreview|null>(null); const [securityAuditStatus,setSecurityAuditStatus]=useState(''); const [auditPruneConfirmation,setAuditPruneConfirmation]=useState('');
 const [unifiedTrace,setUnifiedTrace]=useState<ProvenanceTrace|null>(null); const [traceTitle,setTraceTitle]=useState(''); const [traceKind,setTraceKind]=useState(''); const [traceLineage,setTraceLineage]=useState<ExtractionLineage|null>(null); const [traceSource,setTraceSource]=useState<SourceRecord|null>(null); const [traceUrl,setTraceUrl]=useState(''); const [traceLocator,setTraceLocator]=useState(''); const [traceDetail,setTraceDetail]=useState(''); const [traceEvidence,setTraceEvidence]=useState<EvidenceRecord[]>([]); const [traceHistory,setTraceHistory]=useState<HistoryRow[]>([]); const [traceStatus,setTraceStatus]=useState('');
 const reportPayloadError=(error:unknown)=>{console.error(error);alert(errorMessage(error,'Unexpected API response error'))};
